diff --git a/src/lib.rs b/src/lib.rs
index fa89644..f3bc9ba 100644
--- a/src/lib.rs
+++ b/src/lib.rs
@@ -2,14 +2,19 @@

 use std::collections::HashMap;

-/// Parse `key=value` lines into a map.
-///
-/// FIXME: this panics on malformed input; callers want a Result they can handle.
-pub fn parse_kv(input: &str) -> HashMap<String, String> {
+/// Parse `key=value` lines into a map, returning an error on any malformed line.
+pub fn parse_kv(input: &str) -> Result<HashMap<String, String>, String> {
     let mut m = HashMap::new();
     for line in input.lines() {
-        let (k, v) = line.split_once('=').unwrap();
-        m.insert(k.trim().to_string(), v.trim().to_string());
+        if line.trim().is_empty() {
+            continue;
+        }
+        match line.split_once('=') {
+            Some((k, v)) => {
+                m.insert(k.trim().to_string(), v.trim().to_string());
+            }
+            None => return Err(format!("malformed line (no '='): {line:?}")),
+        }
     }
-    m
+    Ok(m)
 }
